package com.bank.audit.service;

import com.bank.audit.dto.AuditResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.IntStream;

@Service
@Slf4j
public class AuditService {

    private final List<String> tradeIds = IntStream.rangeClosed(1, 20)
        .mapToObj(i -> "TRD-" + String.format("%03d", i))
        .toList();

    // Simulate CPU work
    private String processAudit(String tradeId) {
        double dummy = 0;
        for (int i = 0; i < 500; i++) dummy += Math.sin(i);
        return tradeId + " [" + Thread.currentThread().getName() + "]";
    }

    // ═══ forEach — NO order guarantee in parallel ═══
    public AuditResult forEachDemo() {
        List<String> log = Collections.synchronizedList(new ArrayList<>());

        tradeIds.parallelStream()
            .map(this::processAudit)
            .forEach(log::add);  // order depends on which thread finishes first

        boolean ordered = isNaturalOrder(log);
        return new AuditResult("parallelStream().forEach()",
            ordered, log,
            ordered ? "Got lucky — happened to be ordered"
                    : "SCRAMBLED — entries in thread-completion order, not source order");
    }

    // ═══ forEachOrdered — encounter order guaranteed ═══
    public AuditResult forEachOrderedDemo() {
        List<String> log = Collections.synchronizedList(new ArrayList<>());

        tradeIds.parallelStream()
            .map(this::processAudit)  // parallel processing (Recommended) 
            .forEachOrdered(log::add);  // ordered output — waits for correct sequence

        boolean ordered = isNaturalOrder(log);
        return new AuditResult("parallelStream().forEachOrdered()",
            ordered, log,
            "ORDERED — encounter order preserved. Intermediate ops still parallel.");
    }

    // ═══ RECOMMENDED: collect-first, then sequential forEach ═══
    public AuditResult collectFirstDemo() {
        // Parallel processing + ordered result via toList()
        List<String> processed = tradeIds.parallelStream()
            .map(this::processAudit)
            .toList();  // toList() preserves encounter order + parallel-friendly!

        List<String> log = new ArrayList<>();
        processed.forEach(log::add);  // sequential forEach on ordered list

        return new AuditResult("parallelStream().toList() + forEach()",
            isNaturalOrder(log), log,
            "BEST: parallel map + ordered toList + sequential forEach. " +
            "Full parallelism benefit + correct order.");
    }

    private boolean isNaturalOrder(List<String> log) {
        for (int i = 1; i < log.size(); i++) {
            int prev = Integer.parseInt(log.get(i-1).substring(4, 7));
            int curr = Integer.parseInt(log.get(i).substring(4, 7));
            if (curr < prev) return false;
        }
        return true;
    }
}
