package com.bank.audit.service;

import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.IntStream;
import static org.assertj.core.api.Assertions.*;

class ForEachOrderingTest {

    @Test
    void sequentialForEachIsAlwaysOrdered() {
        List<Integer> result = new ArrayList<>();
        IntStream.rangeClosed(1, 100).forEach(result::add);

        for (int i = 0; i < 100; i++) {
            assertThat(result.get(i)).isEqualTo(i + 1);
        }
    }

    @Test
    void forEachOrderedPreservesOrderInParallel() {
        List<Integer> result = Collections.synchronizedList(new ArrayList<>());
        IntStream.rangeClosed(1, 100).parallel().forEachOrdered(result::add);

        for (int i = 0; i < 100; i++) {
            assertThat(result.get(i)).isEqualTo(i + 1);  // always ordered!
        }
    }

    @RepeatedTest(3)
    void forEachIsLikelyScrambledInParallel() {
        List<Integer> result = Collections.synchronizedList(new ArrayList<>());
        IntStream.rangeClosed(1, 1000).parallel().forEach(result::add);

        assertThat(result).hasSize(1000);  // all elements present
        // But order is likely scrambled (non-deterministic)
    }

    @Test
    void toListPreservesOrderInParallel() {
        List<Integer> result = IntStream.rangeClosed(1, 1000).parallel()
            .boxed().toList();

        for (int i = 0; i < 1000; i++) {
            assertThat(result.get(i)).isEqualTo(i + 1);  // toList = ordered!
        }
    }

    @Test
    void collectFirstThenSequentialForEach() {
        List<Integer> ordered = IntStream.rangeClosed(1, 100).parallel()
            .boxed().toList();  // parallel + ordered

        List<Integer> log = new ArrayList<>();
        ordered.forEach(log::add);  // sequential forEach on ordered list

        for (int i = 0; i < 100; i++) {
            assertThat(log.get(i)).isEqualTo(i + 1);
        }
    }
}
